// Falls back to a friendly error state rather than crashing the entire app.
// Usage: <ErrorBoundary fallback={<p>Something went wrong.</p>}><MyComponent /></ErrorBoundary>

import { useState } from 'react'

type ErrorBoundaryProps = {
  fallback: React.ReactNode
  children: React.ReactNode
}

interface ErrorBoundaryState {
  hasError: boolean
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props)
    this.state = { hasError: false }
  }

  static getDerivedStateFromError(_error: Error) {
    // Update state so the next render will show the fallback UI.
    return { hasError: true }
  }

  render() {
    if (this.state.hasError) {
      const { fallback } = this.props
      return fallback ? <div className="p-6 text-center text-muted">{fallback}</div> : null
    }
    return this.props.children
  }
}

